mapper.select:
SELECT t.id AS id, t.task_type AS taskType, t.dispatch_time AS dispatchTime, t.deadline_time AS deadlineTime, t.status AS status, a.name AS areaName, u.nickname AS executeUserName, t.finish_time AS finishTime, t.task_progress AS taskProgress, t.transfer_reason AS transferReason, t.remark AS remark, t.reserve1 AS reserve1, t.reserve2 AS reserve2, t.creator AS creator, t.updater AS updater, t.create_time AS createTime, t.update_time AS updateTime FROM check_task t LEFT JOIN area_info a ON t.area_id = a.id AND a.deleted = 0 LEFT JOIN user_info u ON t.execute_user_id = u.id AND u.deleted = 0 WHERE t.deleted = 0
AND t.task_type = #{reqVO.taskType}
AND t.dispatch_time BETWEEN #{reqVO.dispatchTime[0]} AND #{reqVO.dispatchTime[1]}
AND t.deadline_time BETWEEN #{reqVO.deadlineTime[0]} AND #{reqVO.deadlineTime[1]}
AND t.status = #{reqVO.status}
AND t.area_id = #{reqVO.areaId}
AND t.execute_user_id = #{reqVO.executeUserId}
AND t.finish_time BETWEEN #{reqVO.finishTime[0]} AND #{reqVO.finishTime[1]}
AND t.task_progress LIKE CONCAT('%', #{reqVO.taskProgress}, '%')
AND t.transfer_reason LIKE CONCAT('%', #{reqVO.transferReason}, '%')
AND t.remark LIKE CONCAT('%', #{reqVO.remark}, '%')
ORDER BY t.id DESC

SELECT COUNT(*) FROM check_task t WHERE t.deleted = 0 AND t.status IN ('待派发', '待认领', '处理中')
AND t.create_time BETWEEN FROM_UNIXTIME(#{reqVO.startTime}) AND FROM_UNIXTIME(#{reqVO.endTime})
AND t.area_id = #{reqVO.areaId}

SELECT COUNT(*) FROM check_task t WHERE t.deleted = 0 AND t.status = '已完成'
AND t.create_time BETWEEN FROM_UNIXTIME(#{reqVO.startTime}) AND FROM_UNIXTIME(#{reqVO.endTime})
AND t.area_id = #{reqVO.areaId}
